15  type Grouping = 'priority' | 'assignee';
16  const PAGE_SIZE = 3;
17  
18  function groupIssues(issues: Issue[], by: Grouping): [string, number][] {
19    const counts = new Map<string, number>();
20    for (const issue of issues) {
21      const key =
22        by === 'priority'
23          ? issue.priority
24          : TEAM.find((p) => p.id === issue.assignee)?.name ?? 'Unassigned';
25      counts.set(key, (counts.get(key) ?? 0) + 1);
26    }
27    return Array.from(counts.entries()).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
28  }
