30  export function Reports({ issues }: { issues: Issue[] }) {
31    const classes = useStyles();
32    const [age, setAge] = useState<[number, number]>([0, 30]);
33    const [grouping, setGrouping] = useState<Grouping>('priority');
34    const [page, setPage] = useState(1);
35  
36    const inRange = issues.filter((i) => i.daysOpen >= age[0] && i.daysOpen <= age[1]);
37    const groups = groupIssues(inRange, grouping);
38    const pages = Math.max(1, Math.ceil(groups.length / PAGE_SIZE));
39    const shown = groups.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
40  
41    return (
42      <section className={classes.root} aria-labelledby="reports-title">
43        <Typography id="reports-title" variant="h5" component="h1">
44          Reports
45        </Typography>
46        <div className={classes.controls}>
47          <RangeSlider
48            id="age-label"
49            label="Days open"
50            min={0}
51            max={30}
52            value={age}
53            unit=" days"
54            onChange={(_, value) => {
55              setAge(value as [number, number]);
56              setPage(1);
57            }}
58          />
59          <ToggleButtonGroup
60            exclusive
61            size="small"
62            value={grouping}
63            onChange={(_, value: Grouping | null) => {
64              if (value) {
65                setGrouping(value);
66                setPage(1);
67              }
68            }}
69            aria-label="Group by"
70          >
71            <ToggleButton value="priority">By priority</ToggleButton>
72            <ToggleButton value="assignee">By assignee</ToggleButton>
73          </ToggleButtonGroup>
74        </div>
75        <Typography>{inRange.length} issues</Typography>
76        <List aria-label="Groups">
77          {shown.map(([name, count]) => (
78            <ListItem key={name}>
79              <ListItemText primary={name} secondary={`${count} issues`} />
80            </ListItem>
81          ))}
82        </List>
83        <Pagination count={pages} page={page} onChange={(_, p) => setPage(p)} shape="circular" />
84      </section>
85    );
